/**
 * infographic-steps — vertical step-by-step process visualization.
 *
 * Two or three steps form a connected vertical timeline in portrait or a
 * horizontal row in landscape. Animation: the connector draws in reading order,
 * the circles pop in together, and the editable labels follow. Exit cascade
 * slides each step left and fades in reading order.
 *
 * Block structure (docs/blocks.md):
 *   background — brand atmosphere or supplied/stock media (SceneBackground)
 *   caption    — TemplateText headline in the top text area (subtle archetype)
 *   hero       — StepsList primitive (timeline + labels + cascade exit)
 */

import React from "react";
import { parseList } from "../parse-list";
import type { SceneTemplateProps } from "./types";
import { resolveTokens } from "../theme";
import { TemplateText } from "./template-text";
import { StepsList } from "../primitives/infographic/StepsList";
import { SceneBackground, getMediaBackgroundProps } from "./scene-background";

export const InfographicStepsTemplate: React.FC<SceneTemplateProps> = ({
  variables,
  style,
  progress,
  motionProgress = progress,
  beatIntensity,
  width,
  height,
  textArchetype,
  safeZone,
  sceneDuration,
  backgroundEffect,
  isPlaying,
}) => {
  const { primary, foreground, font } = resolveTokens(style);
  const textColor = foreground;
  const textsRaw = String(variables.texts || "");

  const stepLabels = parseList(variables.steps, 3);
  const stepEmojis = parseList(variables.stepEmojis, 3);

  // textArchetype is intentionally unused — the headline always uses the
  // subtle archetype so the step cascade carries the motion.
  void textArchetype;

  return (
    <div
      style={{
        width,
        height,
        backgroundColor: "#000",
        position: "relative",
        overflow: "hidden",
        fontFamily: font,
      }}
    >
      {/* [slot: background] Brand atmosphere or cinematic supplied/stock media. */}
      <SceneBackground
        style={style}
        progress={progress}
        sceneDuration={sceneDuration}
        width={width}
        height={height}
        {...getMediaBackgroundProps(variables)}
        backgroundEffect={backgroundEffect}
        seed={textsRaw}
        isPlaying={isPlaying}
        beatIntensity={beatIntensity}
      />

      {/* [slot: caption] Headline — top text area */}
      <TemplateText
        motionProgress={motionProgress}
        typeTreatment={resolveTokens(style).preset.type}
        archetype="subtle"
        text={String(variables.texts ?? "")}
        progress={progress}
        sceneDuration={sceneDuration ?? 3}
        width={width}
        height={height}
        position="top"
        sizeRole="headline"
        safeZone={safeZone}
        font={font}
        color={textColor}
        beatIntensity={beatIntensity}
      />

      {/* [slot: hero] Step circles + titles — shared primitive */}
      <StepsList
        progress={motionProgress}
        width={width}
        height={height}
        steps={stepLabels.map((title) => ({ title }))}
        stepEmojis={stepEmojis}
        accent={primary}
        textColor={textColor}
        font={font}
        beatIntensity={beatIntensity}
        safeZone={safeZone}
      />
    </div>
  );
};

/**
 * SceneBackground — shared backdrop component for any scene template that
 * wants to support both a brand-color gradient and stock media (Pexels
 * photo / video) as an alternate atmosphere.
 *
 * Usage:
 *   <SceneBackground
 *     style={style}
 *     progress={progress}
 *     sceneDuration={sceneDuration}
 *     width={width}
 *     height={height}
 *     mediaUrl={String(variables.mediaUrl || "")}
 *     mediaType={String(variables.mediaType || "auto")}
 *     seed={String(variables.texts || "")}
 *     isPlaying={isPlaying}
 *   />
 *   ... template's content layered on top
 *
 * Behavior:
 *   - Brand gradient is the always-on backdrop (uses BrandGradientOverlay).
 *   - When mediaUrl is set and mediaType isn't "gradient", the photo/video
 *     covers the gradient. Vignette + bottom-half darken give the content
 *     contrast against busy footage.
 *   - mediaType="gradient" deliberately ignores mediaUrl and renders only
 *     the brand gradient. First-class atmospheric mode.
 *   - When mediaUrl is empty / 404s / Pexels search returned nothing,
 *     gradient shows through cleanly (matches every other gradient-backed
 *     template).
 *
 * Extracted from bg-media.tsx so any template can compose it. bg-media
 * now uses this component too — its "media is the scene" identity comes
 * from how it positions the title (centered, full-frame), not from
 * duplicated render logic.
 */

import React, { useEffect, useRef } from "react";
import type { TemplateStyle } from "../template-context";
import { BrandGradientOverlay } from "../backgrounds";
import { getBackgroundTransform } from "../backgrounds";

const VIDEO_EXTENSIONS = [".mp4", ".webm", ".mov", ".m4v", ".avi"];

function isVideoUrl(url: string): boolean {
  try {
    const pathname = new URL(url).pathname.toLowerCase();
    return VIDEO_EXTENSIONS.some((ext) => pathname.endsWith(ext));
  } catch {
    const lower = url.toLowerCase();
    return VIDEO_EXTENSIONS.some((ext) => lower.endsWith(ext));
  }
}

export type ResolvedMediaType = "photo" | "video" | "gradient";

export type MediaPosition = "center" | "top" | "bottom" | "left" | "right";
export type MediaTreatment = "subtle" | "cinematic" | "text-safe";

const MEDIA_POSITIONS: Record<MediaPosition, string> = {
  center: "center center",
  top: "center top",
  bottom: "center bottom",
  left: "left center",
  right: "right center",
};

export function resolveMediaPosition(value: string): string {
  return MEDIA_POSITIONS[value as MediaPosition] ?? MEDIA_POSITIONS.center;
}

export function resolveMediaTreatment(value: string): MediaTreatment {
  return value === "subtle" || value === "text-safe" ? value : "cinematic";
}

export interface MediaTreatmentLayer {
  id: "vignette" | "full-wash" | "center-scrim" | "bottom-scrim";
  background: string;
  style?: React.CSSProperties;
}

/** Export-safe contrast recipes. Overlays only: SVG capture cannot rely on CSS filters. */
export function getMediaTreatmentLayers(value: string): MediaTreatmentLayer[] {
  const treatment = resolveMediaTreatment(value);
  const vignette: MediaTreatmentLayer = {
    id: "vignette",
    background:
      treatment === "subtle"
        ? "radial-gradient(ellipse at center, transparent 45%, rgba(0,0,0,0.28) 100%)"
        : "radial-gradient(ellipse at center, transparent 30%, rgba(0,0,0,0.55) 80%, rgba(0,0,0,0.75) 100%)",
  };
  if (treatment === "subtle") return [vignette];

  const cinematic: MediaTreatmentLayer[] = [
    vignette,
    {
      id: "center-scrim",
      background:
        treatment === "text-safe"
          ? "radial-gradient(ellipse 90% 56% at 50% 50%, rgba(0,0,0,0.36) 0%, rgba(0,0,0,0.18) 55%, transparent 84%)"
          : "radial-gradient(ellipse 85% 50% at 50% 50%, rgba(0,0,0,0.22) 0%, rgba(0,0,0,0.10) 50%, transparent 80%)",
    },
    {
      id: "bottom-scrim",
      background:
        treatment === "text-safe"
          ? "linear-gradient(to top, rgba(0,0,0,0.68) 0%, transparent 100%)"
          : "linear-gradient(to top, rgba(0,0,0,0.5) 0%, transparent 100%)",
      style: { top: "55%" },
    },
  ];

  if (treatment === "text-safe") {
    cinematic.splice(1, 0, {
      id: "full-wash",
      background: "rgba(0,0,0,0.30)",
    });
  }
  return cinematic;
}

export function resolveMediaType(
  mediaType: string,
  mediaUrl: string,
): ResolvedMediaType {
  if (mediaType === "gradient") return "gradient";
  if (mediaType === "video") return "video";
  if (mediaType === "photo") return "photo";
  // "auto" — detect from URL extension
  return mediaUrl && isVideoUrl(mediaUrl) ? "video" : "photo";
}

export function getMediaBackgroundProps(variables: Record<string, unknown>) {
  return {
    mediaUrl: String(variables.mediaUrl || ""),
    mediaType: String(variables.mediaType || "auto"),
    mediaPoster: String(variables.mediaPoster || ""),
    mediaPosition: String(variables.mediaPosition || "center"),
    mediaTreatment: String(variables.mediaTreatment || "cinematic"),
  };
}

export interface SceneBackgroundProps {
  style: TemplateStyle;
  progress: number;
  sceneDuration?: number;
  width: number;
  height: number;
  mediaUrl?: string;
  mediaType?: string;
  /** Still image URL shown while the <video> backdrop decodes its first
   *  frame. Without it the element renders transparent during the
   *  ~50–400ms decode window and the gradient flashes through. */
  mediaPoster?: string;
  /** Cover-crop focal anchor. Keeps the important edge/subject visible. */
  mediaPosition?: string;
  /** Overlay recipe: subtle, cinematic, or stronger text-safe contrast. */
  mediaTreatment?: string;
  /** Background motion effect (drift / pulse / Ken Burns). Applied to the photo/video. */
  backgroundEffect?: string;
  /** Stable seed for the gradient breathing animation. Pass the scene's
   *  text content (or any stable string) — it's hashed deterministically. */
  seed?: number | string;
  /** Pause video when preview is paused. Defaults to true (export path). */
  isPlaying?: boolean;
  beatIntensity?: number;
}

export const SceneBackground: React.FC<SceneBackgroundProps> = ({
  style,
  progress,
  sceneDuration,
  width: _width, // accepted for symmetry; not currently used in render
  height: _height,
  mediaUrl = "",
  mediaType = "auto",
  mediaPoster,
  mediaPosition = "center",
  mediaTreatment = "cinematic",
  backgroundEffect,
  seed,
  isPlaying = true,
  beatIntensity = 0,
}) => {
  void _width;
  void _height;
  const resolved = resolveMediaType(mediaType, mediaUrl);
  const showMedia = resolved !== "gradient" && !!mediaUrl;
  const resolvedPosition = resolveMediaPosition(mediaPosition);
  const resolvedTreatment = resolveMediaTreatment(mediaTreatment);
  const treatmentLayers = getMediaTreatmentLayers(resolvedTreatment);

  const gradSeed =
    typeof seed === "number"
      ? seed
      : typeof seed === "string"
        ? seed.split("").reduce((acc, c) => acc + c.charCodeAt(0), 0)
        : 0;

  const bgTransform = getBackgroundTransform(
    backgroundEffect,
    progress,
    beatIntensity,
  );

  // Video playback control — same pause/seek logic bg-media used pre-extract.
  const videoRef = useRef<HTMLVideoElement>(null);
  const lastProgress = useRef(progress);
  const videoStarted = useRef(false);

  useEffect(() => {
    const vid = videoRef.current;
    if (!vid) return;
    if (!isPlaying) {
      vid.pause();
      videoStarted.current = false;
      return;
    }
    const progressChanged = Math.abs(progress - lastProgress.current) > 0.001;
    lastProgress.current = progress;
    if (progressChanged && !videoStarted.current) {
      vid.playbackRate = 1;
      vid.currentTime = 0;
      vid.play().catch(() => {});
      videoStarted.current = true;
    } else if (!progressChanged && videoStarted.current) {
      vid.pause();
      videoStarted.current = false;
    }
  }, [progress, isPlaying]);

  // Release the decoder on unmount. Without this, iOS Safari keeps the
  // video's decoder buffer alive after the React node is gone — each
  // scene transition (or play/pause/play cycle that remounts the active
  // scene) leaks one decoder, eventually crossing the renderer's memory
  // ceiling and triggering "A problem repeatedly occurred." Same recipe
  // as #409's CanvasPreview preload cleanup: pause → clear src → load().
  // Capture the ref at mount-time so the cleanup uses the same node we
  // mounted (the ref's .current is stale by unmount).
  useEffect(() => {
    const vid = videoRef.current;
    return () => {
      if (!vid) return;
      vid.pause();
      vid.removeAttribute("src");
      vid.load();
    };
  }, []);

  return (
    <>
      <BrandGradientOverlay
        style={style}
        progress={progress}
        sceneDuration={sceneDuration}
        seed={gradSeed}
      />

      {showMedia &&
        (resolved === "video" ? (
          <video
            ref={videoRef}
            src={mediaUrl}
            // Poster paints during the decode window so the user sees the
            // (still) first frame instead of a transparent <video> letting
            // the brand gradient show through. Pexels returns a thumbnail
            // image alongside each video; fillPexelsUrls stores it in
            // `variables.mediaPoster`. Layered defense alongside preload="auto"
            // below: on desktop the byte preloader makes decode fast, on
            // mobile (where the preloader skips video pre-mounting to dodge
            // the iOS Safari memory crash) the poster is the primary shield.
            poster={mediaPoster || undefined}
            muted
            loop
            playsInline
            // preload="auto" — without it, browsers default to "metadata":
            // they only load the container/dimensions, not the byte stream
            // needed to decode frames. The element then renders transparent
            // until the first decoded frame arrives, letting the brand
            // gradient flash through whenever a scene mid-playback transitions
            // to a media backdrop. The parent preloader caches the bytes, but
            // decoder state is per-element, so the active mount still has to
            // decode the first frame; "auto" kicks that work off the instant
            // the element mounts.
            preload="auto"
            data-media-position={mediaPosition}
            style={{
              position: "absolute",
              inset: 0,
              width: "100%",
              height: "100%",
              objectFit: "cover",
              objectPosition: resolvedPosition,
              transform: bgTransform.transform,
              transformOrigin: bgTransform.transformOrigin,
            }}
          />
        ) : (
          <div
            data-media-position={mediaPosition}
            style={{
              position: "absolute",
              inset: 0,
              transform: bgTransform.transform,
              transformOrigin: bgTransform.transformOrigin,
              backgroundImage: `url(${mediaUrl})`,
              backgroundSize: "cover",
              backgroundPosition: resolvedPosition,
            }}
          />
        ))}

      {showMedia &&
        treatmentLayers.map((layer) => (
          <div
            key={layer.id}
            data-media-treatment={resolvedTreatment}
            data-media-overlay={layer.id}
            style={{
              position: "absolute",
              inset: 0,
              background: layer.background,
              pointerEvents: "none",
              ...layer.style,
            }}
          />
        ))}
    </>
  );
};

/**
 * StepsList — the `steps` template composes this component (background and
 * headline stay in the template), so the two can never drift.
 *
 * Numbered (or emoji) step circles form a compact timeline in portrait and
 * a horizontal sequence in landscape, with a shared bouncy spring pop-in,
 * title fade-up, and a left-cascade exit. The three steps enter together so
 * the full sequence remains visible as one composition.
 *
 * Layout owns its own absolute positioning — drop into a scene that
 * already paints a background + headline above. The primitive renders
 * the step blocks only.
 */

import * as React from "react";
import {
  interpolate,
  spring,
  type SpringConfig,
} from "../../motion";
import {
  withOpacity,
  autoTextColor,
} from "../../theme";
import { TOP_TEXT_AREA_RATIO } from "../../backgrounds";
import { fitTextSize, stripPipe } from "../../typography";
import { TOKEN_DEFAULTS } from "../../theme";
import { Emoji } from "../../emoji";
import type { SafeZone } from "../../template-context";

// Bouncy pop — matches Remotion reference (damping 8, stiffness 200)
const SPRING_POP: SpringConfig = { damping: 8, stiffness: 200 };
// Snappy slide — for titles
const SPRING_TITLE: SpringConfig = { damping: 18, stiffness: 200 };

// ─── Typed component (direct use from templates) ────────────────

/**
 * Props for StepsList.
 *
 * - `progress` (required): scene progress 0→1 driving all animations.
 * - `width` / `height` (required): scene viewport. Drives portrait/landscape
 *   layout switch and the orientation-aware scale factor.
 * - `steps` (required): 1–4 step entries. Only `title` is used in the
 *   verbatim layout; `description` is accepted for forward-compat but not
 *   rendered (matches the source template). Truncated to 4.
 * - `stepEmojis` (optional): per-step emoji glyph; falls back to a numbered
 *   circle (`1`, `2`, `3`, `4`) when entry is empty / array shorter than `steps`.
 * - `accent` (optional, default `#00e5a0`): brand accent — number color +
 *   radial-glow tint + circle box-shadow.
 * - `textColor` (optional, default `#ffffff`): step-title color.
 * - `font` (optional, default `Inter`).
 * - `beatIntensity` (optional, default `0`): accepted for API parity with
 *   other primitives; currently unused (source doesn't beat-modulate steps).
 */
export interface StepsListProps {
  progress: number;
  width: number;
  height: number;
  steps: Array<{ title: string; description?: string }>;
  stepEmojis?: string[];
  accent?: string;
  textColor?: string;
  font?: string;
  beatIntensity?: number;
  safeZone?: SafeZone;
}

export interface StepsLayoutItem {
  x: number;
  y: number;
  circleRadius: number;
  labelLeft: number;
  labelTop: number;
  labelWidth: number;
  labelFontSize: number;
}

export interface StepsLayout {
  mode: "portrait-timeline" | "landscape-row";
  items: StepsLayoutItem[];
}

/**
 * Safe-zone-aware geometry shared by the renderer and regression tests.
 * Four portrait steps use a compact editorial timeline rather than four
 * oversized centered badges, leaving a predictable text column and bottom
 * breathing room for social-player chrome.
 */
export function computeStepsLayout({
  width,
  height,
  labels,
  safeZone = { top: 0, right: 0, bottom: 0, left: 0 },
}: {
  width: number;
  height: number;
  labels: string[];
  safeZone?: SafeZone;
}): StepsLayout {
  const stepCount = Math.max(1, Math.min(labels.length, 4));
  const s = Math.min(width, height) / 1080;
  const textAreaBottom = Math.max(height * TOP_TEXT_AREA_RATIO, safeZone.top);

  if (width > height) {
    const availableWidth = Math.max(1, width - safeZone.left - safeZone.right);
    const sectionWidth = availableWidth / stepCount;
    const circleRadius = Math.min(104 * s, sectionWidth * 0.25);
    const y = Math.min(
      height * 0.55,
      height - safeZone.bottom - circleRadius - 86 * s,
    );

    return {
      mode: "landscape-row",
      items: labels.slice(0, 4).map((label, index) => {
        const x = safeZone.left + sectionWidth * (index + 0.5);
        const labelWidth = sectionWidth * 0.76;
        return {
          x,
          y,
          circleRadius,
          labelLeft: x - labelWidth / 2,
          labelTop: y + circleRadius + 20 * s,
          labelWidth,
          labelFontSize: fitTextSize(label, 42 * s, labelWidth, { minScale: 0.72 }),
        };
      }),
    };
  }

  const contentTop = textAreaBottom;
  const contentBottom = Math.max(contentTop + 1, height - safeZone.bottom);
  const rowHeight = (contentBottom - contentTop) / stepCount;
  const circleRadius = Math.min(82 * s, rowHeight * 0.27);
  const x = safeZone.left + circleRadius + 48 * s;
  const labelLeft = x + circleRadius + 42 * s;
  const labelWidth = Math.max(1, width - safeZone.right - labelLeft);

  return {
    mode: "portrait-timeline",
    items: labels.slice(0, 4).map((label, index) => {
      const y = contentTop + rowHeight * (index + 0.5);
      return {
        x,
        y,
        circleRadius,
        labelLeft,
        labelTop: y - circleRadius,
        labelWidth,
        labelFontSize: fitTextSize(label, 50 * s, labelWidth, { minScale: 0.68 }),
      };
    }),
  };
}

export const StepsList: React.FC<StepsListProps> = ({
  progress,
  width,
  height,
  steps,
  stepEmojis = [],
  accent = TOKEN_DEFAULTS.primary,
  textColor = "#ffffff",
  font = TOKEN_DEFAULTS.font,
  beatIntensity = 0,
  safeZone,
}) => {
  void beatIntensity;
  const s = Math.min(width, height) / 1080;

  const stepLabels = steps.slice(0, 4).map((st) => stripPipe(String(st.title || "")));
  const hasEmojis = stepEmojis.some((e) => (e || "").length > 0);
  const isLandscape = width > height;
  const layout = computeStepsLayout({ width, height, labels: stepLabels, safeZone });
  const connectorPairs = layout.items.slice(0, -1).map((item, index) => ({
    item,
    next: layout.items[index + 1],
  }));
  const lineProgress = interpolate(progress, [0.07, 0.62], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // ── Animation timing ──────────────────────────────────────────
  const firstStep = 0.08;

  // ── Exit cascade — slide left + fade in reading order ────────
  const EXIT_START = 0.78;
  const EXIT_DURATION = 0.10;
  const EXIT_STAGGER = 0.04;
  const exitForIndex = (i: number) => {
    const start = EXIT_START + i * EXIT_STAGGER;
    const raw = interpolate(progress, [start, start + EXIT_DURATION], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
    const eased = raw * raw; // ease-in
    return { translateX: -90 * s * eased, fade: 1 - eased };
  };

  return (
    <>
      {connectorPairs.map(({ item, next }, index) => {
        const exit = exitForIndex(index);
        const segmentProgress = interpolate(
          lineProgress,
          [index / connectorPairs.length, (index + 1) / connectorPairs.length],
          [0, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
        );

        return (
          <div
            key={`step-connector-${index}`}
            style={layout.mode === "portrait-timeline" ? {
              position: "absolute",
              left: item.x - 2 * s,
              top: item.y + item.circleRadius,
              width: 4 * s,
              height: Math.max(
                0,
                next.y - next.circleRadius - (item.y + item.circleRadius),
              ),
              borderRadius: 999,
              background: `linear-gradient(to bottom, ${withOpacity(accent, 0.9)}, ${withOpacity(textColor, 0.22)})`,
              transform: `translateX(${exit.translateX}px) scaleY(${segmentProgress})`,
              transformOrigin: "top",
              opacity: 0.75 * exit.fade,
            } : {
              position: "absolute",
              left: item.x + item.circleRadius,
              top: item.y - 2 * s,
              width: Math.max(
                0,
                next.x - next.circleRadius - (item.x + item.circleRadius),
              ),
              height: 4 * s,
              borderRadius: 999,
              background: `linear-gradient(to right, ${withOpacity(accent, 0.9)}, ${withOpacity(textColor, 0.22)})`,
              transform: `translateX(${exit.translateX}px) scaleX(${segmentProgress})`,
              transformOrigin: "left",
              opacity: 0.75 * exit.fade,
            }}
          />
        );
      })}

      {layout.items.map((pos, i) => {
        const circleRadius = pos.circleRadius;
        const circleSize = circleRadius * 2;
        const emojiFontSize = circleRadius * (isLandscape ? 0.9 : 0.8);
        const numberFontSize = circleRadius * 0.7;
        const itemStart = firstStep;

        const circleP = spring(
          interpolate(progress, [itemStart, itemStart + 0.12], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          }),
          SPRING_POP,
        );
        const circleScale = interpolate(circleP, [0, 1], [0, 1]);

        const contentDelay = itemStart + 0.03;
        const contentOpacity = interpolate(progress, [contentDelay, contentDelay + 0.05], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        const titleDelay = itemStart + 0.05;
        const titleP = spring(
          interpolate(progress, [titleDelay, titleDelay + 0.10], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          }),
          SPRING_TITLE,
        );
        const titleSlide = isLandscape
          ? (1 - titleP) * 40 * s
          : (1 - titleP) * 120 * s;
        const titleOpacity = interpolate(progress, [titleDelay, titleDelay + 0.05], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        const emoji = hasEmojis ? (stepEmojis[i] || "") : "";
        const glowOpacity = circleScale * 0.2;
        const exit = exitForIndex(i);

        return (
          <div
            key={`step-${i}`}
            data-template-item="steps"
            style={{
              position: "absolute",
              top: pos.y - circleRadius,
              left: 0,
              width,
              height: circleSize,
              transform: `translateX(${exit.translateX}px)`,
              opacity: exit.fade,
            }}
          >
            {/* Radial glow */}
            <div
              style={{
                position: "absolute",
                top: -circleRadius * 0.6,
                left: pos.x - circleRadius * 1.75,
                width: circleRadius * 3.5,
                height: circleRadius * 3.5,
                borderRadius: "50%",
                background: `radial-gradient(circle, ${withOpacity(accent, 0.4)} 0%, transparent 70%)`,
                opacity: glowOpacity,
                pointerEvents: "none",
              }}
            />

            {/* Circle — numbered mode fills solid accent with an
                auto-contrast numeral: the old accent-on-translucent
                combo went illegible whenever accent ≈ background.
                Emoji mode keeps the translucent circle (emoji glyphs
                carry their own color). Matches infographic-steps.tsx. */}
            <div
              style={{
                position: "absolute",
                left: pos.x - circleRadius,
                top: 0,
                width: circleSize,
                height: circleSize,
                borderRadius: "50%",
                backgroundColor: emoji ? "rgba(255,255,255,0.15)" : accent,
                border: "2px solid rgba(255,255,255,0.2)",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                transform: `scale(${circleScale})`,
                boxShadow: `0 0 ${20 * s}px ${withOpacity(accent, glowOpacity)}`,
              }}
            >
              {emoji ? (
                <Emoji char={emoji} size={emojiFontSize} verticalAlign="middle" style={{ opacity: contentOpacity }} />
              ) : (
                <span
                  style={{
                    fontSize: numberFontSize,
                    fontWeight: 800,
                    color: autoTextColor(accent),
                    fontFamily: font,
                    lineHeight: 1,
                    opacity: contentOpacity,
                  }}
                >
                  {i + 1}
                </span>
              )}
            </div>

            {/* Title — beside the portrait timeline or below the landscape row. */}
            <div
              style={{
                position: "absolute",
                left: pos.labelLeft,
                top: pos.labelTop - (pos.y - circleRadius),
                width: pos.labelWidth,
                height: isLandscape ? 80 * s : circleSize,
                display: "flex",
                alignItems: isLandscape ? "flex-start" : "center",
                justifyContent: isLandscape ? "center" : "flex-start",
                fontSize: pos.labelFontSize,
                fontWeight: 600,
                color: textColor,
                fontFamily: font,
                letterSpacing: -0.3,
                textAlign: isLandscape ? "center" : "left",
                opacity: titleOpacity,
                transform: isLandscape ? `translateY(${titleSlide}px)` : `translateX(${titleSlide}px)`,
                textShadow: "0 1px 6px rgba(0,0,0,0.1)",
                lineHeight: 1.12,
                whiteSpace: "normal",
              }}
            >
              {stepLabels[i]}
            </div>
          </div>
        );
      })}
    </>
  );
};

import * as React from "react";

const NATIVE_EMOJI_FONT = "Apple Color Emoji,Segoe UI Emoji,Noto Color Emoji,sans-serif";
const NATIVE_EMOJI = /\p{Emoji_Presentation}|\p{Regional_Indicator}|\u{FE0F}|\u{20E3}/u;

/** True for emoji-presentation graphemes, not plain symbols such as ★ or ✓. */
export function isNativeEmoji(char: string): boolean {
  return NATIVE_EMOJI.test(char);
}

export interface EmojiProps {
  /** The emoji character or grapheme cluster, e.g. "🎉" or "👩‍💻". */
  char: string;
  /** Font size in px. */
  size: number;
  /** vertical-align for inline flow. Defaults to a glyph-like baseline nudge. */
  verticalAlign?: React.CSSProperties["verticalAlign"];
  /** Extra styles merged onto the native emoji span. */
  style?: React.CSSProperties;
}

/** Render emoji with the viewer's OS font while preserving text-style symbols. */
export const Emoji: React.FC<EmojiProps> = ({ char, size, verticalAlign = "-0.15em", style }) => {
  const nativeEmoji = isNativeEmoji(char);
  return (
    <span
      role={nativeEmoji ? "img" : undefined}
      aria-label={nativeEmoji ? char : undefined}
      style={{
        ...(nativeEmoji ? { fontFamily: NATIVE_EMOJI_FONT } : {}),
        fontSize: size,
        lineHeight: 1,
        display: "inline-block",
        verticalAlign,
        ...style,
      }}
    >
      {char}
    </span>
  );
};

/**
 * TemplateText — unified text component for scene templates.
 *
 * Replaces the per-template hand-rolled text rendering with a single component
 * that owns: archetype motion lifecycle (entrance + hold + exit), font sizing,
 * position, beat pulse, and safe zone.
 *
 * Each template declares its constraints (position + sizeRole) at the call site;
 * the user/AI picks the archetype. Templates that can only show text at the top
 * just always pass position="top".
 *
 * Example — a data template (caption above a chart):
 *
 *   <TemplateText
 *     archetype={textArchetype}
 *     text={variables.title}
 *     progress={progress}
 *     sceneDuration={sceneDuration}
 *     width={width}
 *     height={height}
 *     position="top"
 *     sizeRole="caption"
 *   />
 *
 * Example — a media template (full-frame headline):
 *
 *   <TemplateText
 *     archetype={textArchetype}
 *     text={variables.headline}
 *     progress={progress}
 *     sceneDuration={sceneDuration}
 *     width={width}
 *     height={height}
 *     position="center"
 *     sizeRole="headline"
 *     beatIntensity={beatIntensity}
 *   />
 *
 * Note: `textArchetype` is destructured from props (a scene-level
 * field on `SceneTemplateProps`), NOT read from `variables`. Copying
 * the wrong pattern silently no-ops — the executor routes
 * `setSceneVariable("textArchetype", ...)` to the scene-level field,
 * never into variables, so `variables.textArchetype` is always
 * undefined.
 */

import {
  renderArchetype,
  normalizeArchetype,
  type TextArchetype,
  type ArchetypeRender,
} from "../typography";
import type { TypeTreatment } from "../theme";
import { renderWithEmoji, planTypewriterEmoji } from "../emoji/emoji-text";
import { Emoji } from "../emoji";

export type TextPosition = "top" | "center" | "bottom";
export type TextSizeRole = "headline" | "caption" | "label";

export interface SafeZone {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

export interface TemplateTextProps {
  archetype: TextArchetype;
  text: string;
  /** Scene progress 0→1. */
  progress: number;
  /** Presentation clock; VideoFrame keeps it on the complete scene timeline. */
  motionProgress?: number;
  /** Scene duration in seconds — drives entrance/exit phase scaling. */
  sceneDuration: number;
  /** Frame width in pixels (1080 in production, smaller in previews). */
  width: number;
  /** Frame height in pixels (1920 in production). */
  height: number;
  /** Where the text box sits in the frame. Templates declare this. */
  position?: TextPosition;
  /** Size envelope. Templates declare this. */
  sizeRole?: TextSizeRole;
  /** Preset type treatment — weight/tracking/size/case shift from style.preset. */
  typeTreatment?: TypeTreatment;
  /** Padding from frame edges. Defaults to a 24px box. */
  safeZone?: SafeZone;
  /** Font family. */
  font?: string;
  /** Fill color. */
  color?: string;
  /** Beat intensity 0→1 (currently unused — kept for forward compat). */
  beatIntensity?: number;
}

const DEFAULT_SAFE_ZONE: SafeZone = { top: 24, right: 24, bottom: 24, left: 24 };
const DEFAULT_FONT =
  "ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";

// ─── Typography constants ───────────────────────────────────────
// All em-based so they scale with font size and behave consistently across
// font families. Values from print/motion-design conventions:
//
//  - Big text (display/headline) gets TIGHTER tracking and TIGHTER leading.
//    -0.022em (≈ -2.2%) is the sweet spot for 48–88px headlines on most
//    sans-serifs (Inter, Helvetica, SF Pro, Manrope, Geist).
//  - Word-spacing kept subtle (≤0.08em). CSS word-spacing is ADDITIVE on
//    top of the natural space char, so what looks like "a touch of
//    rhythm" in print becomes a visible double-gap on 80px motion
//    headlines (especially under wordStagger, where each word renders
//    as an inline-block and the gap between them is preserved). Old
//    values (0.16/0.18/0.22 em) added ~13–18px per gap on display
//    type — the "too much space between words" symptom.
//  - Line-height 1.1 for headlines, 1.5 for body — Bringhurst-aligned ratios.
//  - kern + liga always on so any font's pair-kerning and ligatures fire
//    consistently (works across Inter, Manrope, SF, IBM Plex, etc.).
const TYPO = {
  headline: {
    letterSpacing: "-0.022em",
    wordSpacing: "0.04em",
    lineHeight: 1.1,
  },
  caption: {
    letterSpacing: "-0.012em",
    wordSpacing: "0.06em",
    lineHeight: 1.25,
  },
  label: {
    letterSpacing: "-0.005em",
    wordSpacing: "0.10em",
    lineHeight: 1.4,
  },
};
const FONT_FEATURES = '"kern" 1, "liga" 1';

// Drop shadow tuned to give crisp edges on retina without muddying text on
// saturated gradients. Earlier two-layer shadow (1px tight + 16px wide) cast
// dark halos that made gradient-backed text look smudged. A single barely-
// there shadow is enough for edge definition; bg-media adds its own dark
// scrim for legibility over photos, so we don't need to compensate here.
function dropShadowFor(textColor: string): string {
  const dark = isLikelyDark(textColor);
  const tone = dark ? "rgba(255,255,255,0.15)" : "rgba(0,0,0,0.2)";
  return `0 1px 2px ${tone}`;
}

function isLikelyDark(color: string): boolean {
  // Crude luminance check — handles #rrggbb and #rgb. Anything we can't parse
  // (named colors, rgb()) defaults to "not dark" so the heavier shadow shows.
  const m = color.replace("#", "");
  if (m.length === 3) {
    const r = parseInt(m[0] + m[0], 16);
    const g = parseInt(m[1] + m[1], 16);
    const b = parseInt(m[2] + m[2], 16);
    return (r * 299 + g * 587 + b * 114) / 1000 < 128;
  }
  if (m.length === 6) {
    const r = parseInt(m.slice(0, 2), 16);
    const g = parseInt(m.slice(2, 4), 16);
    const b = parseInt(m.slice(4, 6), 16);
    return (r * 299 + g * 587 + b * 114) / 1000 < 128;
  }
  return false;
}
// ─── Font sizing matrix ─────────────────────────────────────────
// Mirrors what production templates actually render today, ported from:
//   - text-overlay.tsx (headline: 80/64/48 × s_min by char count)
//   - infographic-steps.tsx (caption: ~44 × s_min capped by layout)

/**
 * Compute heroWord font size for a single word. Each active word fills its
 * own moment — trailer convention. Center can go large (480ref cap); top
 * stays inside the top zone height so it doesn't crash into the animation
 * or data viz below.
 */
function computeHeroFontSize(
  wordChars: number,
  position: TextPosition,
  width: number,
  height: number,
  safeZone: SafeZone,
): number {
  const chars = Math.max(wordChars, 1);
  const s_min = Math.min(width, height) / 1080;
  const widthBudget = (width - safeZone.left - safeZone.right) * 0.92;
  const pxPerChar = 0.58; // bold sans-serif approximation
  const widthCap = widthBudget / (chars * pxPerChar);

  if (position === "center") {
    return Math.min(480 * s_min, widthCap);
  }

  // Top/bottom: keep the word inside its zone (~28% of frame height) with
  // 80% headroom for entrance overshoot + breathe. Reference target 220ref
  // so even short words stay big without overflowing the zone.
  const heightCap = height * 0.28 * 0.8;
  return Math.min(220 * s_min, widthCap, heightCap);
}

/**
 * Smooth interpolation between max and min font size based on character count.
 * Avoids the visible "jump" you get from bucket boundaries when copy length
 * crosses a threshold (e.g., 25→26 chars dropping headline from 80px to 64px).
 *
 * Exported so templates that lay out their own text can match the headline
 * curve instead of inventing their own bucketed scaling.
 *
 * Returns size at 1080-reference scale; caller multiplies by s_min.
 */
export function smoothSize(chars: number, maxChars: number, max: number, min: number): number {
  const t = Math.max(0, Math.min(1, chars / maxChars));
  // Slight curve so short text stays at maxSize longer before scaling down.
  const eased = t * t;
  return max - (max - min) * eased;
}

function computeFontSize(
  archetype: TextArchetype,
  text: string,
  role: TextSizeRole,
  position: TextPosition,
  width: number,
  height: number,
  safeZone: SafeZone,
): { fontSize: number; fontWeight: number } {
  const s_min = Math.min(width, height) / 1080;

  // heroWord container fontSize uses the longest word as a safe fallback. The
  // ACTIVE-word size is recomputed per-render in the "hero" render branch
  // (via computeHeroFontSize) so each word fills its own moment optimally —
  // trailer convention.
  if (archetype === "heroWord") {
    const longestChars = text
      .split(/\s+/)
      .filter(Boolean)
      .reduce((m, w) => Math.max(m, w.length), 1);
    return {
      fontSize: computeHeroFontSize(longestChars, position, width, height, safeZone),
      fontWeight: 800,
    };
  }

  const chars = text.length;

  // Smooth scaling, minimums set so even long copy stays readable in production
  // (1080 reference). Numbers tuned to match — but improve on — the previous
  // bucketed system.
  if (role === "headline") {
    // Floor 60 (was 48) — matches the typography guideline "Titles/headlines
    // 60-86px at 1080" and lifts long-copy headlines off the body-text floor
    // that left ProblemSolution-shaped statements feeling small. Max held at
    // 88 so short, punchy headlines still fill the frame.
    const refSize = smoothSize(chars, /* maxChars */ 70, /* max */ 88, /* min */ 60);
    return { fontSize: refSize * s_min, fontWeight: 700 };
  }

  if (role === "caption") {
    const refSize = smoothSize(chars, 80, 48, 32);
    return { fontSize: refSize * s_min, fontWeight: 600 };
  }

  // label
  const refSize = smoothSize(chars, 80, 34, 24);
  return { fontSize: refSize * s_min, fontWeight: 500 };
}

// ─── Positioning ───────────────────────────────────────────────

function positionStyle(
  position: TextPosition,
  height: number,
  safeZone: SafeZone,
): React.CSSProperties {
  switch (position) {
    case "top":
      return {
        top: safeZone.top + height * 0.06,
        height: height * 0.28,
        alignItems: "flex-start",
      };
    case "bottom":
      return {
        bottom: safeZone.bottom + height * 0.06,
        height: height * 0.28,
        alignItems: "flex-end",
      };
    case "center":
    default:
      return {
        top: 0,
        bottom: 0,
        alignItems: "center",
      };
  }
}

// ─── Component ─────────────────────────────────────────────────

export const TemplateText: React.FC<TemplateTextProps> = ({
  archetype: archetypeRaw,
  text: textRaw,
  progress,
  motionProgress = progress,
  sceneDuration,
  width,
  height,
  position = "center",
  sizeRole = "headline",
  typeTreatment,
  safeZone = DEFAULT_SAFE_ZONE,
  font = DEFAULT_FONT,
  color = "#FFFFFF",
  beatIntensity = 0,
}) => {
  // Defensive coerce: TemplateText is downstream of ~16 templates that pass
  // their own `variables.X` strings. If any one of them passes undefined
  // (missing variable on a freshly added scene, stale saved config, custom
  // template not setting a field), the unguarded `.split` / `.length` calls
  // below crash the entire preview. Treat undefined/non-string as
  // empty so a single bad scene doesn't take everything down. Warn in dev
  // so the upstream gap still surfaces.
  const textSafe = typeof textRaw === "string" ? textRaw : "";
  const isDevelopment = (import.meta as ImportMeta & { env?: { DEV?: boolean } }).env?.DEV;
  if (textRaw !== undefined && typeof textRaw !== "string" && isDevelopment) {
    console.warn("[TemplateText] received non-string text:", textRaw);
  }
  // `|` is the AI's explicit line-break convention for headline copy
  // ("Built for speed.|Designed for you."). Convert centrally so EVERY
  // template that renders text through TemplateText honors it — bg-media
  // used to convert locally while confetti/emojiBurst/etc. rendered the
  // pipe literally. Whitespace around the pipe is trimmed so spaced and
  // unspaced pipes produce identical output. The container's
  // `white-space: pre-line` renders the resulting `\n` as a hard break.
  // Templates that legitimately render pipes (code, terminal commands)
  // don't flow through TemplateText, so they're unaffected.
  const text = textSafe.replace(/\s*\|\s*/g, "\n");
  // Normalize the archetype prop so unknown names fall back safely.
  const archetype = normalizeArchetype(archetypeRaw);
  const scale = Math.min(width, height) / 1080;
  // Motion pacing applies at every size role — a calm video should ease its
  // captions in too, not just its headlines. (The rest of the treatment is
  // headline-only; see `tt` below.)
  const result: ArchetypeRender = renderArchetype(
    archetype,
    progress,
    scale,
    text,
    sceneDuration,
    typeTreatment?.phaseScale ?? 1,
    motionProgress,
  );
  const { fontSize, fontWeight } = computeFontSize(
    archetype,
    text,
    sizeRole,
    position,
    width,
    height,
    safeZone,
  );

  // beatIntensity reserved for future use; currently a no-op on text body.
  void beatIntensity;

  const baseTypo = TYPO[sizeRole];
  // Preset type treatment. Absent (or the default preset's zero-deltas) leaves
  // every value exactly as it was, so unpresetted configs are unaffected.
  const tt = sizeRole === "headline" ? typeTreatment : undefined;
  // Only rewrite a value the preset actually changes — reformatting
  // letterSpacing with a zero delta would alter the emitted string (and every
  // stability snapshot) without changing the render.
  const typo = tt
    ? {
        ...baseTypo,
        ...(tt.trackingDeltaEm !== 0
          ? {
              letterSpacing: `${Number(
                (parseFloat(baseTypo.letterSpacing) + tt.trackingDeltaEm).toFixed(4),
              )}em`,
            }
          : {}),
        ...(tt.transform ? { textTransform: tt.transform } : {}),
      }
    : baseTypo;
  const presetWeight = tt ? Math.min(900, Math.max(100, fontWeight + tt.weightDelta)) : fontWeight;
  const presetSize = tt ? fontSize * tt.sizeScale : fontSize;
  const textShadow = dropShadowFor(color);

  const containerStyle: React.CSSProperties = {
    position: "absolute",
    left: 0,
    right: 0,
    display: "flex",
    justifyContent: "center",
    padding: `0 ${safeZone.right}px 0 ${safeZone.left}px`,
    color,
    fontFamily: font,
    fontWeight: presetWeight,
    fontSize: presetSize,
    textAlign: "center",
    pointerEvents: "none",
    fontFeatureSettings: FONT_FEATURES,
    textRendering: "optimizeLegibility",
    WebkitFontSmoothing: "antialiased",
    MozOsxFontSmoothing: "grayscale",
    // Respect explicit newlines — the centralized `|` → `\n` conversion
    // above (and callers passing real newlines) rely on this. Multiple
    // spaces still collapse normally; only `\n` and CRLF break.
    whiteSpace: "pre-line",
    ...(textShadow ? { textShadow } : {}),
    ...typo,
    ...positionStyle(position, height, safeZone),
  };

  if (result.kind === "block") {
    return (
      <div style={containerStyle}>
        <div
          style={{
            opacity: result.block.opacity,
            transform: `${result.block.transform}`,
            // Inherit letter-spacing from the container's typography defaults
            // unless the archetype explicitly overrides (e.g., for animated tracking).
            ...(result.block.letterSpacing ? { letterSpacing: result.block.letterSpacing } : {}),
            ...(result.block.willChange ? { willChange: result.block.willChange } : {}),
            maxWidth: "85%",
          }}
        >
          {renderWithEmoji(result.text, fontSize)}
        </div>
      </div>
    );
  }

  if (result.kind === "typewriter") {
    // Render every character as its own span so the FULL TEXT always sets the
    // layout — wrapping is decided by the complete string, not the typed
    // prefix. The cursor is overlaid with position:absolute from the last
    // typed char so it doesn't break the word it's inside.
    const chars = text.split("");
    // Map cluster-start code-unit indices → full emoji graphemes so emoji use
    // the native font even in the per-char typewriter reveal. Indexing
    // stays on text.length (UTF-16 units) so result.visibleChars / charExits
    // line up exactly; continuation units of a cluster render nothing.
    const emojiPlan = planTypewriterEmoji(text);
    const cursorBar = {
      position: "absolute" as const,
      width: "0.08em",
      height: "0.88em",
      background: "currentColor",
      borderRadius: "0.01em",
      pointerEvents: "none" as const,
    };
    return (
      <div style={containerStyle}>
        <div
          style={{
            opacity: result.opacity,
            maxWidth: "85%",
            whiteSpace: "pre-wrap",
            position: "relative",
          }}
        >
          {chars.map((ch, i) => {
            const isTyped = i < result.visibleChars;
            const isLastTyped = i === result.visibleChars - 1;
            const anchorCursor = isLastTyped && result.cursor;
            const charExit = result.charExits?.[i];
            const baseOpacity = isTyped ? 1 : 0;
            const finalOpacity = baseOpacity * (charExit?.opacity ?? 1);
            // During exit the per-char span needs inline-block so translateX
            // takes effect; whiteSpace: pre keeps space chars from collapsing.
            const exitStyle = charExit
              ? {
                  display: "inline-block" as const,
                  transform: `translateX(${charExit.translateX}px)`,
                  whiteSpace: "pre" as const,
                }
              : null;
            // Emoji handling: a cluster-start unit renders the full grapheme;
            // its continuation units render nothing.
            const emojiChar = emojiPlan?.starts.get(i);
            if (emojiPlan?.covered.has(i)) return null;
            return (
              <span
                key={i}
                style={{
                  opacity: finalOpacity,
                  position: anchorCursor ? "relative" : "static",
                  ...(exitStyle ?? {}),
                }}
              >
                {emojiChar ? <Emoji char={emojiChar} size={fontSize} /> : ch}
                {anchorCursor && (
                  <span
                    aria-hidden
                    style={{
                      ...cursorBar,
                      left: "100%",
                      top: "0.08em",
                      marginLeft: "0.12em",
                    }}
                  />
                )}
              </span>
            );
          })}
          {result.visibleChars === 0 && result.cursor && (
            <span
              aria-hidden
              style={{
                ...cursorBar,
                left: 0,
                top: "0.08em",
              }}
            />
          )}
        </div>
      </div>
    );
  }

  if (result.kind === "words") {
    // Render words inline-block with REAL space chars between them — word
    // spacing inherits from the container's typography defaults, matching
    // every other archetype's wrap behavior.
    return (
      <div style={containerStyle}>
        <div
          style={{
            opacity: result.blockOpacity,
            transform: `${result.blockTransform} `,
            maxWidth: "85%",
          }}
        >
          {result.words.map((w, i) => (
            <span key={i}>
              <span
                style={{
                  display: "inline-block",
                  opacity: w.style.opacity,
                  transform: w.style.transform,
                }}
              >
                {renderWithEmoji(w.text, fontSize)}
              </span>
              {i < result.words.length - 1 ? " " : ""}
            </span>
          ))}
        </div>
      </div>
    );
  }

  if (result.kind === "hero") {
    // Per-word sizing: each active word fills its own moment optimally.
    const perWordFontSize = computeHeroFontSize(
      result.word.length,
      position,
      width,
      height,
      safeZone,
    );
    // Fixed-height slot so words of different sizes don't jump vertically.
    // Slot is the max possible hero size for this position; lineHeight: 1 on
    // the inner word locks the glyph box to the font height so flex-center
    // lands the glyph at the same Y for every word.
    const slotHeight =
      position === "center" ? 480 * scale : Math.min(220 * scale, height * 0.28 * 0.8);
    return (
      <div style={{ ...containerStyle, fontSize: perWordFontSize }}>
        <div
          style={{
            height: slotHeight,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              opacity: result.opacity,
              transform: `${result.transform} `,
              lineHeight: 1,
              ...(result.letterSpacing ? { letterSpacing: result.letterSpacing } : {}),
            }}
          >
            {renderWithEmoji(result.word, perWordFontSize)}
          </div>
        </div>
      </div>
    );
  }

  return null;
};

/**
 * EmojiText / renderWithEmoji — split a string into text runs + emoji runs,
 * rendering each emoji with the viewer's native emoji font while leaving
 * everything else as plain text.
 *
 * Segmentation: grapheme clusters via Intl.Segmenter so ZWJ sequences
 * (👩‍💻) and skin-tone modifiers (👍🏽) stay single units. Adjacent emoji
 * clusters each render as their own span in sequence.
 */

import * as React from "react";
import { Emoji, isNativeEmoji } from "./index";

/** Split text into grapheme clusters (ZWJ + skin-tone safe). */
function toGraphemes(text: string): string[] {
  const Seg = (Intl as unknown as { Segmenter?: typeof Intl.Segmenter }).Segmenter;
  if (Seg) {
    const seg = new Seg(undefined, { granularity: "grapheme" });
    const out: string[] = [];
    for (const { segment } of seg.segment(text)) out.push(segment);
    return out;
  }
  // Fallback: code-point spread. Won't keep ZWJ/skin-tone as single units, so
  // those land as separate clusters. Modern browsers all have Segmenter.
  return Array.from(text);
}

export interface RenderWithEmojiOptions {
  /** vertical-align passed to each <Emoji>. */
  verticalAlign?: React.CSSProperties["verticalAlign"];
  /** Extra style merged onto each emoji span. */
  emojiStyle?: React.CSSProperties;
}

/**
 * Split `text` into an array of React nodes — plain-text strings interleaved
 * with <Emoji> spans for every emoji cluster. Returns a single-element
 * `[text]` fast-path when there are no emoji (the common case), so
 * non-emoji text pays ~one regex test.
 *
 * @param text         the string to render
 * @param fontSizePx   surrounding font size in px (emoji box = this size)
 */
export function renderWithEmoji(
  text: string,
  fontSizePx: number,
  opts?: RenderWithEmojiOptions,
): React.ReactNode[] {
  if (!text) return [text];
  // Cheap bail-out: if the whole string has no emoji-range codepoint, return
  // it untouched (no segmentation, no array churn) — the hot path for the vast
  // majority of titles/bodies.
  if (!isNativeEmoji(text)) return [text];

  const clusters = toGraphemes(text);
  const nodes: React.ReactNode[] = [];
  let textBuf = "";
  let key = 0;

  const flushText = () => {
    if (textBuf) {
      nodes.push(textBuf);
      textBuf = "";
    }
  };

  for (const cluster of clusters) {
    if (isNativeEmoji(cluster)) {
      flushText();
      nodes.push(
        <Emoji
          key={`e${key++}`}
          char={cluster}
          size={fontSizePx}
          verticalAlign={opts?.verticalAlign}
          style={opts?.emojiStyle}
        />,
      );
    } else {
      textBuf += cluster;
    }
  }
  flushText();
  return nodes;
}

/**
 * Per-code-unit emoji plan for the typewriter archetype, which reveals text
 * one UTF-16 code unit at a time and indexes by `text.length`. We can't just
 * call renderWithEmoji there (it would re-segment and desync the visibleChars
 * counter), so this maps each cluster's START code-unit index to the full emoji
 * and marks the cluster's CONTINUATION indices as covered (render nothing for
 * them — the start index's span already contains the whole cluster).
 *
 * Returns null when the text contains no emoji (the common case),
 * so the typewriter render keeps its plain per-char path.
 */
export interface EmojiTypewriterPlan {
  /** code-unit index → full emoji cluster char (cluster start). */
  starts: Map<number, string>;
  /** code-unit indices that are continuations of a cluster (render nothing). */
  covered: Set<number>;
}

export function planTypewriterEmoji(text: string): EmojiTypewriterPlan | null {
  if (!text || !isNativeEmoji(text)) return null;
  const starts = new Map<number, string>();
  const covered = new Set<number>();
  let idx = 0;
  let found = false;
  for (const cluster of toGraphemes(text)) {
    const len = cluster.length; // UTF-16 code units
    if (isNativeEmoji(cluster)) {
      found = true;
      // Store the WHOLE cluster char (not just the start unit) so callers can
      // pass it straight to <Emoji> without splitting a grapheme cluster.
      starts.set(idx, cluster);
      for (let k = 1; k < len; k++) covered.add(idx + k);
    }
    idx += len;
  }
  return found ? { starts, covered } : null;
}

export interface EmojiTextProps {
  /** The text to render with emoji in the native operating-system font. */
  children: string;
  /** Surrounding font size in px — sizes each emoji to match a glyph. */
  fontSize: number;
  verticalAlign?: React.CSSProperties["verticalAlign"];
  emojiStyle?: React.CSSProperties;
}

/**
 * Inline wrapper around renderWithEmoji. Renders a React.Fragment of text +
 * emoji spans. Use where a component currently renders a raw `{text}`
 * child and you have the surrounding font size in px.
 */
export const EmojiText: React.FC<EmojiTextProps> = ({
  children,
  fontSize,
  verticalAlign,
  emojiStyle,
}) => {
  const text = typeof children === "string" ? children : "";
  return <>{renderWithEmoji(text, fontSize, { verticalAlign, emojiStyle })}</>;
};

/**
 * Scene template types.
 *
 * A template is a reusable React component that defines how a scene looks.
 * It declares the variables an editor or model may provide
 * and receives universal settings as props.
 *
 * Templates are searchable by AI via description, category, jobs, register,
 * and useWhen guidance.
 * The variable schema enables any LLM to fill in template variables via JSON.
 */

import type { ResolvedTokens } from "../theme";
import type { SafeZone, TemplateStyle } from "../template-context";

/**
 * Props passed to every scene template component.
 *
 * All animation must be driven by `progress` (0→1). No CSS animations,
 * no Framer Motion, no requestAnimationFrame. Use interpolate/spring
 * from animation-utils.ts.
 *
 * Scale factor: use `Math.min(width, height) / 1080` — normalizes to
 * the short edge so visuals are consistent across portrait and landscape.
 */
export interface SceneTemplateProps {
  variables: Record<string, unknown>;
  style: TemplateStyle;
  /** 0→1 through the scene's duration */
  progress: number;
  /** Presentation clock. Active templates receive the same complete 0→1 timeline as progress. */
  motionProgress?: number;
  /** 0→1 beat pulse intensity */
  beatIntensity: number;
  /** 1080 (portrait) or 1920 (landscape) */
  width: number;
  /** 1920 (portrait) or 1080 (landscape) */
  height: number;
  /** Video-level default text effect (for templates that opt in via usesGlobalTextEffect) */
  textArchetype?: string;
  /** How text leaves the scene (fade / shrink / pop / blur-scale). Falls back to a sensible default per textArchetype when undefined. */
  /** Video-level default background effect (for templates that opt in via usesGlobalBackgroundEffect) */
  backgroundEffect?: string;
  /** Platform-aware safe zone insets in pixels — use for text placement */
  safeZone: SafeZone;
  /** Scene duration in seconds — use for time-based (not progress-based) animations */
  sceneDuration?: number;
  /**
   * Brand tokens already resolved from `style`. Built-in templates import
   * resolveTokens directly; an ejected `custom_*` scene can't import anything,
   * so without this it has no way to reach the same values and ends up
   * hardcoding white, black and shadows — the body then looks generic next to
   * a frame that IS using the brand.
   */
  tokens?: ResolvedTokens;
  /**
   * True when the preview player is actively advancing progress; false when paused.
   * Templates that play HTML5 <video> elements should pause them when this is false.
   * Undefined (export capture path) is treated as true.
   */
  isPlaying?: boolean;
}

// ─── List variable parser ──────────────────────────────────────
//
// Single source of truth for parsing list-shaped template variables
// (items, texts, words, steps, itemEmojis, oldItems, newItems, etc.)
//
// Accepts any of:
//   - string[]                          → returned as-is (trimmed, filtered)
//   - { label | name | text | title | value }[]  → text extracted
//   - JSON-encoded array string         → parsed then normalized
//   - comma-separated string            → split on commas
//   - single string / number / boolean  → wrapped as single-item array
//   - null / undefined                  → []
//
// Never splits on semicolons. A single item may contain any punctuation.
// Use this everywhere instead of ad-hoc `.split(",")`.

export function parseList(value: unknown, max?: number): string[] {
  if (value === null || value === undefined) return [];

  let arr: unknown[];

  if (Array.isArray(value)) {
    arr = value;
  } else if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed) return [];
    // Try JSON array first — supports real array output from AI
    if (trimmed.startsWith("[") && trimmed.endsWith("]")) {
      try {
        const parsed = JSON.parse(trimmed);
        arr = Array.isArray(parsed) ? parsed : [trimmed];
      } catch {
        arr = trimmed.split(",");
      }
    } else {
      // Accept a compact comma-separated list.
      arr = trimmed.split(",");
    }
  } else if (typeof value === "number" || typeof value === "boolean") {
    arr = [value];
  } else if (typeof value === "object") {
    arr = [value];
  } else {
    return [];
  }

  const out = arr
    .map((item) => {
      if (item === null || item === undefined) return "";
      if (typeof item === "string") return item.trim();
      if (typeof item === "number" || typeof item === "boolean") return String(item);
      if (typeof item === "object") {
        const o = item as Record<string, unknown>;
        const picked =
          o.label ?? o.name ?? o.text ?? o.title ?? o.description ?? o.value;
        return picked !== undefined ? String(picked).trim() : "";
      }
      return String(item).trim();
    })
    .filter((s) => s.length > 0);

  return typeof max === "number" ? out.slice(0, max) : out;
}
